import { Phase, type ActionProvider, type GameEvent } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { GameActionRequestFactory } from "../../../engine/action_request_factory";
import type { MistPendingNight } from "./pending_night";
import {
  assertMistRosterCurrent,
  mistCasterId,
  openSnakeWindow,
  commitSnakeChoice,
} from "./night_frame";

/** PM already claimed its sole pending owner before any preceding blast/badge await. */
export async function decideSnake(
  world: World,
  events: GameEvent[],
  gateway: ToolGateway,
  provider: ActionProvider,
  pending: MistPendingNight,
  isCurrent: () => boolean,
): Promise<number | null> {
  const actorId = mistCasterId(world, "alchemist"),
    day = pending.day;
  const current = () => pending.status === "committing" && isCurrent();
  if (!current()) throw new Error("snake_window_stale");
  assertMistRosterCurrent(world);
  const candidates = pending.snakeTargets(actorId);
  openSnakeWindow(world, day, candidates, current);
  const request = new GameActionRequestFactory(world, events, day).create({
    phase: Phase.Day,
    actorId,
    allowedTools: ["use_snake"],
    stage: "alchemist_snake",
    requiresAction: true,
    summary: { key: "request.summary.alchemist_snake" },
    context: {
      snake_target: pending.wolfTarget,
      snake_candidates: candidates,
      action_failure_policy: "error",
      allow_fallback: false,
    },
  });
  const action = await provider.getAction(request);
  assertMistRosterCurrent(world);
  if (!current()) throw new Error("snake_window_stale");
  if (action?.name !== "use_snake") throw new Error("snake_action_missing");
  const result = gateway.validateAndSanitize(world, actorId, action, { phase: Phase.Day, day });
  assertMistRosterCurrent(world);
  if (!current() || !result.ok || result.sanitizedCall?.name !== "use_snake")
    throw new Error("snake_action_invalid");
  const targetId = result.sanitizedCall.args.target_id;
  commitSnakeChoice(world, day, actorId, targetId);
  events.push({
    timestamp: Date.now(),
    type: "alchemist_snake_chosen",
    payload: { actorId, day, targetId },
    audience: Object.freeze([actorId]),
  });
  return targetId;
}

/**
 * 负责收集河豚反噬选择，输入为 World、事件数组、Provider／网关、日期与原单元对象。
 * 当前单元／actor 及绑定请求决定资格；校验后先提交回执，再按原票型政策发表揭示与目标。
 * 输出为捕获的目标数组；请求始终在 finally 关闭，库存及原票源归 authority，此处不提交死亡波。
 */
import { ANIMAL_DREAM_POLICY } from "@ai-werewolf-arena/game-contract";
import type { World } from "../../../../core/domain/world";
import type { ActionProvider } from "../../../../core/domain/actions";
import type { GameEvent } from "../../../../core/domain/events";
import { Phase } from "../../../../core/domain/identity";
import { GameActionRequestFactory } from "../../../engine/action_request_factory";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import {
  animalPufferChoiceActor,
  animalAuthoritySnapshot,
  animalPufferReaction,
} from "./authority";
import {
  openAnimalRequest,
  animalRequestScope,
  readAnimalTool,
  commitAnimalRequest,
  closeAnimalRequest,
} from "./requests";
import { appendAnimalFact } from "./facts";
export async function runAnimalPufferChoice(
  world: World,
  events: GameEvent[],
  provider: ActionProvider,
  gateway: ToolGateway,
  day: number,
  unit: object,
): Promise<readonly number[]> {
  const actorId = animalPufferChoiceActor(world, unit);
  if (actorId === null) return [];
  const request = new GameActionRequestFactory(world, events, day).create({
      actorId,
      phase: Phase.Voting,
      allowedTools: ["puffer_retaliate"],
      stage: "puffer_reaction",
      requiresAction: true,
      summary: { key: "action.puffer_retaliate.directive" },
      context: { allow_fallback: false, action_failure_policy: "error" },
    }),
    scope = openAnimalRequest(world, request, unit);
  try {
    const raw = await provider.getAction(request),
      call = readAnimalTool(raw);
    if (animalRequestScope(world, request) !== scope || call?.name !== "puffer_retaliate")
      throw Error("animal_required_action_invalid");
    const valid = gateway.validateAndSanitize(world, actorId, call, {
      phase: Phase.Voting,
      day,
      animalScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw Error("animal_required_action_invalid");
    const receipt = commitAnimalRequest(world, scope, valid.sanitizedCall);
    if (!("activate" in receipt)) throw Error("animal_receipt_invalid");
    appendAnimalFact(world, events, "animal_puffer_decided", {
      policy: ANIMAL_DREAM_POLICY,
      actorId,
      ...receipt,
    });
    const targetIds = [...animalPufferReaction(world, unit)];
    if (receipt.activate) {
      appendAnimalFact(world, events, "animal_puffer_revealed", {
        policy: ANIMAL_DREAM_POLICY,
        day,
        actorId,
        reason: "retaliation",
      });
      const snapshot = animalAuthoritySnapshot(world)!;
      appendAnimalFact(world, events, "animal_puffer_targets", {
        policy: ANIMAL_DREAM_POLICY,
        day,
        actorId,
        targetIds,
        round:
          snapshot.policies!.ballotPolicy === "awa_first_ballot_v1"
            ? 1
            : snapshot.unit!.finalRound!,
      });
    }
    return targetIds;
  } finally {
    closeAnimalRequest(scope);
  }
}

/**
 * 负责雾鸦延迟夜的完整建立、领取、蛇选择及最终伤害准备／完成步骤。输入为经理的延迟原引用、
 * 同一待处理实例和当前性回调；输出同步步骤序列，原蛇 Promise 与准备伤害分别交回经理。
 * 经理唯一保存 pending，仍拥有阶段时钟、公开夜报、实际死亡提交、判胜和外层 abort；本组合不复制权威。
 * 原生命／伤害复制、疗救付款和窗口许可仍归本族原所有者。失败停在当前步骤，不退款、不自动完成或正常关闭。
 */
import type { EntityId, NightSummary } from "@ai-werewolf-arena/game-contract";
import type { ActionProvider } from "../core/domain/actions";
import type { GameEvent } from "../core/domain/events";
import type { World } from "../core/domain/world";
import type { AliveComponent } from "../core/domain/components/alive";
import { aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import type { DamageResolutionResult } from "../core/domain/systems/damage_resolution_system";
import type { DreamNightEffects } from "../core/domain/dream-night-effects";
import { Phase } from "@ai-werewolf-arena/game-contract";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import type { NightManagerLifecycle } from "./night-lifecycle-plan";
import { assertMistRosterCurrent } from "../game/mechanisms/roles/mist_raven/ports";
import { MistPendingNight } from "../game/mechanisms/roles/mist_raven/pending_night";
import { decideSnake } from "../game/mechanisms/roles/mist_raven/snake_window";
import { safeRecordLogicOp } from "../recording/session_recorder";

/** 只读取已交接的同一夜结果；原生命、梦句柄和伤害仍按各自所有者的既有规则处理。 */
export interface MistDelayedNightInput {
  deathLives: ReadonlyMap<EntityId, { life: AliveComponent; version: number | undefined }>;
  summary: Pick<NightSummary, "wolfTarget">;
  damage: DamageResolutionResult;
  dreamFrame: DreamNightEffects;
}

export interface MistDelayedNightOpening {
  readonly world: World;
  readonly cycleDay: number;
  readonly night: MistDelayedNightInput;
}

/** 先核名单／每个原生命，再构造唯一待处理实例；检查失败时经理原字段尚未被新实例替换。 */
export function prepareMistDelayedNight(runtime: MistDelayedNightOpening): MistPendingNight {
  assertMistRosterCurrent(runtime.world);
  for (const [id, scope] of runtime.night.deathLives) {
    if (
      runtime.world.getComponent(id, COMPONENT.Alive) !== scope.life ||
      !scope.life.alive ||
      scope.version === undefined ||
      aliveLifeVersion(scope.life) !== scope.version
    )
      throw new Error("mist_pending_life_stale");
  }
  return new MistPendingNight(
    runtime.world,
    runtime.cycleDay,
    runtime.night.summary.wolfTarget,
    runtime.night.damage,
    runtime.night.dreamFrame,
  );
}

/** 窄读取仍指向经理唯一字段；这里没有第二份 pending、阶段时钟或完成标志。 */
export interface MistDelayedNightSettlementRuntime {
  readonly pending: MistPendingNight | null;
  readonly world: World;
  readonly events: GameEvent[];
  readonly toolGateway: ToolGateway;
  readonly lifecycle: Pick<NightManagerLifecycle, "closeMistNormally">;
  readonly cycleDay: number;
}

/** 同一 current 闭包交给经理的真实死亡提交；这是运行数据，不是 JSON、许可或第二份状态。 */
export interface MistPreparedNightDamage {
  damage: DamageResolutionResult;
  current: () => boolean;
}

/** 两个 yield 都同步交回原对象；恢复协议仅用于这个具体延迟夜，不驱动其它角色或通用清理。 */
export function* settleMistDelayedNight(
  runtime: MistDelayedNightSettlementRuntime,
  actionProvider: ActionProvider,
  dayIsCurrent: () => boolean,
  alreadyClaimed: boolean,
): Generator<Promise<number | null> | MistPreparedNightDamage, void, number | null> {
  const pending = runtime.pending;
  if (!pending) throw new Error("mist_pending_night_missing");
  const current = () => dayIsCurrent() && pending === runtime.pending;
  if (!alreadyClaimed) pending.claim(current);
  // 第一次只交原蛇 Promise：经理在原位置等待，拒绝时不恢复下面的准备／完成步骤。
  const healed = yield decideSnake(
    runtime.world,
    runtime.events,
    runtime.toolGateway,
    actionProvider,
    pending,
    current,
  );
  const damage = pending.prepareFinalDamage(healed, current);
  safeRecordLogicOp({
    scope: "resolution",
    op: "night_damage_resolved",
    phase: Phase.Night,
    status: "ok",
    output: { deaths: damage.deaths, death_sources: damage.deathSources },
  });
  // 第二次交原伤害，经理同步发表夜报并等待真实 DeathResolution；成功之后才允许第三次 next。
  // 死亡提交失败不恢复这里，已付蛇和已发表／标死前缀保留，外层经理沿原路径 abort。
  yield { damage, current };
  assertMistRosterCurrent(runtime.world);
  pending.finish(current);
  runtime.lifecycle.closeMistNormally(runtime.cycleDay);
}

/**
 * 负责放逐投票的实际单位、候选、席位顺序及既有回合／平票／票权政策。
 * 输入为当前玩家与行动；输出为原票据和放逐结果。preVote中断不制造普通开票单位；
 * 首票前开同一单位，王子复收票与PK共用，零放逐、翻牌或映射落空仍属于已开单位。
 * 秘密之身的付款、必需发言与关闭归本族同步序列；本流水线只在原请求点 await，不额外等待未触发路径。
 * Animal复用原token且独占计数／到期政策。警长选举和狼刀维持各自流程，不合并为通用投票器。
 */
import { revealSecretBodyExile } from "../../mechanisms/roles/noble_secret_body/exile-ports";
import { openExileUnit, attachExileUnit } from "../../../core/domain/exile-unit";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  beginAnimalExileUnit,
  recordAnimalBallotRound,
  sealAnimalBallots,
} from "../../mechanisms/roles/animal_dream/authority";
import { runAnimalPufferChoice } from "../../mechanisms/roles/animal_dream/puffer_window";
import { resolveTricksterExile } from "../../mechanisms/roles/trickster/night_frame";
import { assertOrderPrinceOriginalCurrent } from "../../mechanisms/roles/order_prince/authority";
import { runOrderPrinceChoice } from "../../mechanisms/roles/order_prince/voting_window";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { COMPONENT } from "../../../core/domain/components/names";
import { IdentityComponent } from "../../../core/domain/entities/player";
import { VotingRightComponent } from "../../../core/domain/components/voting_right";
import {
  ActionProvider,
  ActionWindow,
  EntityId,
  GameEvent,
  Phase,
  Role,
  TieBreakerStrategy,
  VoteRecord,
  VotingSummary,
} from "../../../core/domain/model";
import { RoleRegistry } from "../../../core/domain/registries/role_registry";
import { ToolGateway } from "../../gateway/tool_gateway";
import { safeRecordLogicOp } from "../../../recording/session_recorder";
import { EventRegistry } from "../event_registry";
import { World } from "../../../core/domain/world";
import { GameActionRequestFactory } from "../action_request_factory";
import { SelfDestructWindow, isSelfDestructWindowEnabled } from "../../../rulesets/self-destruct-window";
import { canBeExiled, canVoteExile } from "../../mechanisms/common/participation";

/**
 * 投票流水线执行结果。
 */
export interface VotingPipelineResult {
  animalUnit?: object;
  animalRetaliation?: readonly number[];
  summary: VotingSummary;
  interrupted: boolean;
  removed: EntityId[];
  selfDestruct?: import("../../../core").SelfDestructSelection;
}

export interface VotingPipelineOptions {
  strictRequired?: boolean;
  orderPrinceRevote?: boolean;
  /** 当前日次由 PhaseManager 显式传入，不能从事件历史反推。 */
  day: number;
  isCurrent?: () => boolean;
  commitSelfDestruct?: (
    choice: import("../../../core").SelfDestructSelection,
  ) => Promise<void | boolean>;
}

export interface VotingPipelineDependencies {
  world: World;
  roleRegistry: RoleRegistry;
  toolGateway: ToolGateway;
  eventRegistry: EventRegistry;
  events: GameEvent[];
}

interface CollectedVote {
  voterId: EntityId;
  targetId: EntityId | null;
  abstain: boolean;
  fallback: boolean;
  voterLife: NonNullable<ReturnType<typeof captureNightLife>>;
  targetLife?: NonNullable<ReturnType<typeof captureNightLife>>;
}

/**
 * 放逐投票流水线：
 * 1) 在 onPreVote 窗口可触发狼人自爆中断。
 * 2) 存活且有投票权玩家依次投票，按权重计票。
 * 3) 调用 EventRegistry 处理白痴免死、警徽销毁等投后钩子。
 */
export class VotingPipeline {
  private static readonly MAX_VOTE_RETRIES = 3;
  private readonly world: World;
  private readonly selfDestructWindow: SelfDestructWindow;
  private readonly toolGateway: ToolGateway;
  private readonly eventRegistry: EventRegistry;
  private readonly events: GameEvent[];

  constructor(dependencies: VotingPipelineDependencies) {
    this.world = dependencies.world;
    this.toolGateway = dependencies.toolGateway;
    this.eventRegistry = dependencies.eventRegistry;
    this.events = dependencies.events;
    this.selfDestructWindow = new SelfDestructWindow(
      this.world,
      dependencies.roleRegistry,
      this.toolGateway,
    );
  }

  async execute(
    config: ReadonlyBoardConfig,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
  ): Promise<VotingPipelineResult> {
    let unitDay: number;
    const requests = new GameActionRequestFactory(this.world, this.events, (unitDay = options.day));
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "voting_pipeline_start",
      phase: Phase.Voting,
      status: "ok",
      input: {
        on_pre_vote_hook: config.hooks.onPreVote,
      },
    });
    if (config.hooks.onPreVote && isSelfDestructWindowEnabled(config, ActionWindow.OnPreVote)) {
      const exploded = await this.selfDestructWindow.execute(
        requests,
        actionProvider,
        ActionWindow.OnPreVote,
        Phase.Voting,
        options.isCurrent,
        options.commitSelfDestruct,
      );
      if (exploded !== null) {
        safeRecordLogicOp({
          scope: "phase_pipeline",
          op: "voting_interrupted_by_self_destruct",
          actorId: exploded.actorId,
          phase: Phase.Voting,
          status: "ok",
        });
        return {
          summary: {
            tally: {},
            target: null,
            removed:
              exploded.targetId === null
                ? [exploded.actorId]
                : [exploded.actorId, exploded.targetId],
          },
          interrupted: true,
          selfDestruct: exploded,
          removed:
            exploded.targetId === null ? [exploded.actorId] : [exploded.actorId, exploded.targetId],
        };
      }
    }

    if (options.isCurrent && !options.isCurrent())
      return { summary: { tally: {}, target: null, removed: [] }, interrupted: false, removed: [] };
    const animalUnit = config.animalDream
      ? beginAnimalExileUnit(
          this.world,
          (unitDay = options.day),
          "exile",
          () => options.isCurrent?.() !== false,
        )
      : undefined;
    // 此门禁已开启一次真实放逐；后续重新收票／PK仍消费同一个对象。
    const exileUnit = openExileUnit(unitDay, "exile", animalUnit);
    const voters = this.world
      .getAliveEntityIds()
      .filter((id) => canVoteExile(this.world, id, options.day));

    // 请求并行执行；Promise.all 保留原投票者顺序，公开票据按该顺序稳定发布。
    const voteResults = await this.collectVotes(voters, requests, actionProvider, options);
    if (options.isCurrent?.() === false)
      return attachExileUnit({ summary: { tally: {}, target: null, removed: [] }, interrupted: false, removed: [] }, exileUnit);
    let { tally, publicVotes } = this.recordVotesInSeatOrder(voteResults, options.day);
    if (animalUnit) recordAnimalBallotRound(this.world, animalUnit, 1, publicVotes);
    if (config.roleSetups.some((setup) => setup.role === Role.OrderPrince && setup.count > 0)) {
      const restarted = await runOrderPrinceChoice(
        this.world,
        requests,
        actionProvider,
        this.toolGateway,
        this.events,
        options.day,
        () => options.isCurrent?.() !== false,
      );
      if (restarted) {
        const previousCurrent = options.isCurrent;
        options = {
          ...options,
          strictRequired: true,
          orderPrinceRevote: true,
          isCurrent: () => {
            assertOrderPrinceOriginalCurrent(this.world);
            if (previousCurrent?.() === false) throw new Error("order_prince_revote_stale");
            return true;
          },
        };
        const freshVoters = this.world
          .getAliveEntityIds()
          .filter((id) => canVoteExile(this.world, id, options.day));
        const fresh = await this.collectVotes(freshVoters, requests, actionProvider, options);
        if (options.isCurrent?.() === false) throw new Error("order_prince_revote_stale");
        ({ tally, publicVotes } = this.recordVotesInSeatOrder(fresh, options.day, true));
      }
    }
    const pk = config.voting?.exilePolicy === "awa_one_pk_v1";
    const maximum = Math.max(
      0,
      ...Object.entries(tally)
        .filter(([id]) => canBeExiled(this.world, Number(id)))
        .map(([, score]) => score),
    );
    const tied =
      maximum > 0
        ? Object.entries(tally)
            .filter(([id, score]) => score === maximum && canBeExiled(this.world, Number(id)))
            .map(([id]) => Number(id))
        : [];
    let round = 1;
    if (pk && tied.length > 1) {
      this.events.push({
        timestamp: Date.now(),
        type: "vote_summary",
        payload: { votes: publicVotes, tally, target: null, round: 1 },
      });
      this.events.push({
        timestamp: Date.now(),
        type: "exile_pk_started",
        payload: { candidates: tied },
      });
      for (const actorId of tied) {
        if (options.isCurrent?.() === false)
          return attachExileUnit({
            summary: { tally: {}, target: null, removed: [] },
            interrupted: false,
            removed: [],
          }, exileUnit);
        const life = captureNightLife(this.world, actorId);
        if (!life || !canBeExiled(this.world, actorId)) {
          if (options.strictRequired) throw new Error("order_prince_pk_candidate_stale");
          continue;
        }
        const request = requests.create({
          phase: Phase.Voting,
          actorId,
          allowedTools: ["speak"],
          stage: "exile_pk_speech",
          requiresAction: true,
          summary: { key: "request.summary.exile_pk" },
          context: {
            exile_candidates: tied,
            round: 2,
            max_rounds: 2,
            ...(options.strictRequired
              ? { action_failure_policy: "error", allow_fallback: false }
              : {}),
          },
        });
        const action = await actionProvider.getAction(request);
        if (options.isCurrent?.() === false)
          return attachExileUnit({
            summary: { tally: {}, target: null, removed: [] },
            interrupted: false,
            removed: [],
          }, exileUnit);
        if (
          action?.name !== "speak" ||
          !livingNightLife(this.world, life) ||
          !canBeExiled(this.world, actorId)
        ) {
          if (options.strictRequired) throw new Error("order_prince_pk_speech_missing_or_stale");
          continue;
        }
        const result = this.toolGateway.validateAndSanitize(this.world, actorId, action, {
          phase: Phase.Voting,
          day: options.day,
        });
        if (
          options.strictRequired &&
          (!result.ok || !result.sanitizedCall || !livingNightLife(this.world, life))
        )
          throw new Error("order_prince_pk_speech_invalid");
        if (result.ok && result.sanitizedCall && livingNightLife(this.world, life))
          this.events.push({
            timestamp: Date.now(),
            type: "day_speech",
            payload: { actorId, text: result.sanitizedCall.args.text },
          });
      }
      const candidates = tied.filter((id) => canBeExiled(this.world, id));
      const revoters = this.world
        .getAliveEntityIds()
        .filter((id) => !tied.includes(id) && canVoteExile(this.world, id, options.day));
      const results = await this.collectVotes(
        revoters,
        requests,
        actionProvider,
        options,
        candidates,
      );
      if (options.isCurrent?.() === false)
        return attachExileUnit({
          summary: { tally: {}, target: null, removed: [] },
          interrupted: false,
          removed: [],
        }, exileUnit);
      ({ tally, publicVotes } = this.recordVotesInSeatOrder(
        results,
        options.day,
        options.strictRequired,
      ));
      round = 2;
      if (animalUnit) recordAnimalBallotRound(this.world, animalUnit, 2, publicVotes, candidates);
    }

    const target = this.pickMajorityTarget(
      Object.fromEntries(
        Object.entries(tally).filter(([id]) => canBeExiled(this.world, Number(id))),
      ),
      pk ? "no_elimination" : (config.tieBreaker?.exileVote ?? "min_id"),
    );
    this.events.push({
      timestamp: Date.now(),
      type: "vote_summary",
      payload: {
        votes: publicVotes,
        tally,
        target,
        ...(pk ? { round } : {}),
      },
    });
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "vote_tally_resolved",
      phase: Phase.Voting,
      status: "ok",
      output: {
        tally,
        target,
      },
    });
    let animalRetaliation: readonly number[] = [];
    if (animalUnit) {
      sealAnimalBallots(this.world, animalUnit);
      animalRetaliation = await runAnimalPufferChoice(
        this.world,
        this.events,
        actionProvider,
        this.toolGateway,
        options.day,
        animalUnit,
      );
    }
    if (target === null) {
      return attachExileUnit({
        summary: {
          tally,
          target: null,
          removed: [],
        },
        interrupted: false,
        removed: [],
        ...(animalUnit ? { animalUnit, animalRetaliation } : {}),
      }, exileUnit);
    }

    const mapped = config.trickster ? resolveTricksterExile(this.world, options.day, target) : null;
    if (mapped)
      this.events.push({ timestamp: Date.now(), type: "exile_target_mapped", payload: mapped });
    const effectiveTarget = mapped?.effectiveId ?? target;
    const thisPipeline = this;
    const reveal = revealSecretBodyExile(
      {
        get enabled() { return config.nobleSecretBody; },
        get world() { return thisPipeline.world; },
        get events() { return thisPipeline.events; },
        get requests() { return requests; },
        get toolGateway() { return thisPipeline.toolGateway; },
        get day() { return options.day; },
        get isCurrent() { return options.isCurrent; },
      },
      effectiveTarget,
    );
    const revealStep = reveal.next();
    if (!revealStep.done) {
      try {
        // 只等待原 Provider；未触发翻牌的同步完成路径不进入此处。
        const action = await actionProvider.getAction(revealStep.value);
        reveal.next(action);
      } finally {
        // Provider 同步抛错／拒绝时驱动本族关闭；已完成或抛错的生成器不会再次关闭 scope。
        reveal.return(false);
      }
      return attachExileUnit({ summary: { tally, target, removed: [] }, removed: [], interrupted: false }, exileUnit);
    }
    const votedOut = mapped?.missed
      ? { removed: [] }
      : this.eventRegistry.onVotedOut(this.world, effectiveTarget, this.events);
    const removed = [...votedOut.removed];

    if (removed.includes(effectiveTarget) && !animalUnit) {
      // 只有真正出局才广播 voted_out；白痴翻牌由事件总线单独广播。
      this.events.push({
        timestamp: Date.now(),
        type: "voted_out",
        payload: {
          target: effectiveTarget,
        },
      });
    }

    return attachExileUnit({
      summary: {
        tally,
        target,
        ...(mapped ? { effectiveTarget: mapped.missed ? null : effectiveTarget } : {}),
        removed,
      },
      interrupted: false,
      removed,
      ...(animalUnit ? { animalUnit, animalRetaliation } : {}),
    }, exileUnit);
  }

  private async collectVotes(
    voters: EntityId[],
    requests: GameActionRequestFactory,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
    candidates?: EntityId[],
  ): Promise<Array<CollectedVote | null>> {
    // 在调用任何 Provider 之前捕获完整轮次；同步测试 Provider 也不能改变后续捕获的原生命。
    const voterLives = voters.map((voterId) => ({
      voterId,
      life: captureNightLife(this.world, voterId),
    }));
    const targetLives = new Map(
      (candidates ?? this.world.getAliveEntityIds()).flatMap((id) => {
        const life = captureNightLife(this.world, id);
        return life ? [[id, life] as const] : [];
      }),
    );
    return Promise.all(
      voterLives.map(({ voterId, life }) =>
        life
          ? this.collectVoterVote(
              voterId,
              life,
              targetLives,
              requests,
              actionProvider,
              options,
              candidates,
            )
          : null,
      ),
    );
  }

  private async collectVoterVote(
    voterId: EntityId,
    voterLife: NonNullable<ReturnType<typeof captureNightLife>>,
    targetLives: ReadonlyMap<EntityId, NonNullable<ReturnType<typeof captureNightLife>>>,
    requests: GameActionRequestFactory,
    actionProvider: ActionProvider,
    options: VotingPipelineOptions,
    candidates?: EntityId[],
  ): Promise<CollectedVote | null> {
    const current = () => {
      const valid =
        options.isCurrent?.() !== false &&
        livingNightLife(this.world, voterLife) &&
        canVoteExile(this.world, voterId, options.day) &&
        !candidates?.includes(voterId);
      if (!valid && options.strictRequired) throw new Error("order_prince_revote_actor_stale");
      return valid;
    };
    const maxRetries = VotingPipeline.MAX_VOTE_RETRIES;
    let retryReason = "";
    const recordRetry = (attempt: number) =>
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_retry_requested",
        actorId: voterId,
        phase: Phase.Voting,
        status: "fallback",
        reason: retryReason,
        output: { attempt, max_retries: maxRetries },
      });

    for (let attempt = 1; attempt <= maxRetries + 1; attempt++) {
      if (!current()) return null;
      const baseRequest = requests.create({
        phase: Phase.Voting,
        actorId: voterId,
        allowedTools: ["vote"],
        stage: candidates
          ? "exile_pk_vote"
          : options.orderPrinceRevote
            ? "order_prince_revote"
            : "voting",
        requiresAction: true,
        summary: { key: "request.summary.exile_vote" },
        context: {
          ...(candidates ? { exile_candidates: candidates, round: 2, max_rounds: 2 } : {}),
          ...(options.strictRequired
            ? { action_failure_policy: "error", allow_fallback: false }
            : {}),
        },
      });
      const request =
        attempt === 1
          ? baseRequest
          : {
              ...baseRequest,
              context: {
                ...baseRequest.context,
                retry_attempt: attempt - 1,
                retry_max: maxRetries,
                retry_reason: retryReason,
                retry_notice_message: { key: "request.retry.exile_vote" as const },
              },
            };
      if (!current()) return null;
      const action = await actionProvider.getAction(request);
      if (!current()) return null;
      if (action?.name !== "vote") {
        retryReason = "no_valid_vote_tool_call";
        if (attempt <= maxRetries) {
          recordRetry(attempt);
          continue;
        }
        break;
      }

      const result = this.toolGateway.validateAndSanitize(this.world, voterId, action, {
        phase: Phase.Voting,
        day: options.day,
        exileCandidates: candidates,
      });
      if (
        !result.ok ||
        !result.sanitizedCall ||
        (!result.sanitizedCall.args.abstain &&
          (!targetLives.get(result.sanitizedCall.args.target_id!) ||
            !livingNightLife(this.world, targetLives.get(result.sanitizedCall.args.target_id!)!)))
      ) {
        retryReason = "invalid_vote_arguments";
        if (attempt <= maxRetries) {
          recordRetry(attempt);
          continue;
        }
        break;
      }
      return {
        voterId,
        targetId: result.sanitizedCall.args.target_id,
        abstain: result.sanitizedCall.args.abstain === true,
        fallback: attempt > 1,
        voterLife,
        ...(result.sanitizedCall.args.target_id !== null
          ? { targetLife: targetLives.get(result.sanitizedCall.args.target_id) }
          : {}),
      };
    }

    if (!current()) return null;
    if (options.strictRequired) throw new Error("order_prince_revote_action_missing_or_invalid");
    // 重试耗尽后仍需原网关接受，才将缺失行动修复为明确弃票。
    const repaired = this.toolGateway.validateAndSanitize(
      this.world,
      voterId,
      { name: "vote", args: { target_id: null, abstain: true } },
      { phase: Phase.Voting, day: options.day, exileCandidates: candidates },
    );
    if (repaired.ok && repaired.sanitizedCall) {
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_repaired_to_abstain",
        actorId: voterId,
        phase: Phase.Voting,
        status: "ok",
        reason: retryReason || "vote_retry_exhausted",
      });
      return { voterId, targetId: null, abstain: true, fallback: true, voterLife };
    }
    safeRecordLogicOp({
      scope: "phase_pipeline",
      op: "vote_rejected",
      actorId: voterId,
      phase: Phase.Voting,
      status: "rejected",
      reason: retryReason || "vote_retry_exhausted",
    });
    return null;
  }

  private recordVotesInSeatOrder(
    votes: Array<CollectedVote | null>,
    day: number,
    strictRequired = false,
  ): {
    tally: Record<number, number>;
    publicVotes: VoteRecord[];
  } {
    const tally: Record<number, number> = {};
    const publicVotes: VoteRecord[] = [];
    for (const vote of votes) {
      if (!vote) continue;
      const { voterId } = vote;
      if (
        !livingNightLife(this.world, vote.voterLife) ||
        (!vote.abstain && (!vote.targetLife || !livingNightLife(this.world, vote.targetLife))) ||
        !canVoteExile(this.world, voterId, day) ||
        (!vote.abstain && vote.targetId !== null && !canBeExiled(this.world, vote.targetId))
      ) {
        if (strictRequired) throw new Error("order_prince_revote_ballot_stale");
        continue;
      }
      let weight = 0;
      if (!vote.abstain && vote.targetId !== null) {
        const voting = this.world.getComponent(voterId, COMPONENT.VotingRight);
        weight = voting?.weight ?? 1;
        tally[vote.targetId] = (tally[vote.targetId] ?? 0) + weight;
      }
      this.events.push({
        timestamp: Date.now(),
        type: "vote_cast",
        payload: {
          actorId: voterId,
          targetId: vote.targetId,
          abstain: vote.abstain,
          weight,
          ...(vote.fallback ? { fallback: true } : {}),
        },
      });
      publicVotes.push({
        actorId: voterId,
        targetId: vote.targetId,
        abstain: vote.abstain,
        weight,
      });
      safeRecordLogicOp({
        scope: "phase_pipeline",
        op: "vote_cast",
        actorId: voterId,
        phase: Phase.Voting,
        status: "ok",
        output: { target_id: vote.targetId, abstain: vote.abstain, weight },
      });
    }
    return { tally, publicVotes };
  }

  /**
   * 依据计票结果选出放逐目标，平票按编号最小值决议。
   */
  private pickMajorityTarget(
    tally: Record<number, number>,
    strategy: TieBreakerStrategy,
  ): EntityId | null {
    const entries = Object.entries(tally);
    if (entries.length === 0) {
      return null;
    }

    entries.sort((a, b) => {
      const voteDiff = b[1] - a[1];
      if (voteDiff !== 0) {
        return voteDiff;
      }
      if (strategy === "min_seat") {
        const aId = Number(a[0]);
        const bId = Number(b[0]);
        const aSeat = this.world.getComponent(aId, COMPONENT.Identity)?.seat ?? aId;
        const bSeat = this.world.getComponent(bId, COMPONENT.Identity)?.seat ?? bId;
        return aSeat - bSeat;
      }
      return Number(a[0]) - Number(b[0]);
    });

    if (entries.length >= 2 && entries[0][1] === entries[1][1]) {
      if (strategy === "no_elimination") {
        return null;
      }
    }

    return Number(entries[0][0]);
  }
}
